t.script:
_onMapLoads = async function () {
    var address = document.getElementById("cities").value;
    $.ajax({
        url: '/geo/location/' + address,
        type: 'post',
        contentType: 'Application/json',
        dataType: 'Application/json',
        data: JSON.stringify({main: address}),
        success: async function(data) {
            var lat_lng = JSON.parse(data);
            if (lat_lng.result) {
                var lat = lat_lng.result.lat;
                var lng = lat_lng.result.lng;
                $('#country_show').val(lat_lng.result.country);
                $('#p_code').val(lat_lng.result.p_code);

                if (lat === 0 && lng === 0) return;

                const location = { lat: lat, lng: lng };
                const { Map } = await google.maps.importLibrary("maps");
                const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");

                const map = new Map(document.getElementById("map"), {
                    zoom: 12,
                    center: location,
                    mapId: "DEMO_MAP_ID",
                });

                const marker = new AdvancedMarkerElement({
                    map: map,
                    position: location,
                    title: "Location",
                });

                map.addListener("click", (mapsMouseEvent) => {
                    const clickedLoc = mapsMouseEvent.latLng.toJSON();
                    new google.maps.InfoWindow({
                        position: mapsMouseEvent.latLng,
                        content: JSON.stringify(clickedLoc, null, 2),
                    }).open(map);

                    var coordinates = JSON.stringify(clickedLoc);
                    $.ajax({
                        url: '/geo/change/' + coordinates,
                        type: 'post',
                        contentType: 'Application/json',
                        data: JSON.stringify({main: coordinates}),
                        error: function(resp) {
                            var addrs = JSON.parse(resp.responseText);
                            if (addrs && addrs.result) {
                                if (addrs.result.suburb) $('#cities').val(addrs.result.suburb);
                                else $('#cities').val(addrs.result.city);
                                $('#p_code').val(addrs.result.p_code);
                                $('#country_show').val(addrs.result.country);
                                $('#geo_state').val("2");
                            }
                        }
                    });
                });
            }
        },
        error: function(data) { console.error("Geo Error", data); }
    });
}
document.getElementById("cities").addEventListener("change", _onMapLoads);

var map;
var marker;
async function _initLeaflet() {
    var address = document.getElementById("cities").value;
    if (!address) return;

    try {
        const response = await fetch('/geo/location/' + address, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({main: address}),
        });
        const data = await response.json();

        // Parse inner JSON if needed or use directly
        // Odoo controllers sometimes double encode or just return dict
        let lat_lng;
        try {
            lat_lng = JSON.parse(data.result);
        } catch(e) {
            lat_lng = data.result || data;
        }

        const result = lat_lng.result || lat_lng;

        if (result) {
            var lat = result.lat;
            var lng = result.lng;

            var countryInput = document.getElementById('country_show');
            if (countryInput) countryInput.value = result.country;

            var pCodeInput = document.getElementById('p_code');
            if (pCodeInput) pCodeInput.value = result.p_code;

            if (lat === 0 && lng === 0) return;

            if (!map) {
                map = L.map('map').setView([lat, lng], 13);
                L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19,
                    attribution: '&copy; <a href="http://www.openstreetmap.org/copyright">OpenStreetMap</a>'
                }).addTo(map);
            } else {
                map.setView([lat, lng], 13);
            }

            if (marker) map.removeLayer(marker);
            marker = L.marker([lat, lng]).addTo(map).bindPopup("Location").openPopup();

            map.off('click');
            map.on('click', async function(e) {
                var coord = {lat: e.latlng.lat, lng: e.latlng.lng};
                if (marker) map.removeLayer(marker);
                marker = L.marker([coord.lat, coord.lng]).addTo(map);

                var coordinates = JSON.stringify(coord);

                try {
                    const resp = await fetch('/geo/change/' + coordinates, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({main: coordinates}),
                    });

                    const respData = await resp.json();
                    let addrs;
                    try {
                        addrs = JSON.parse(respData.result);
                    } catch (e) {
                        addrs = respData.result || respData;
                    }

                    if (addrs && addrs.result) {
                        var cityInput = document.getElementById("cities");
                        if (cityInput) {
                            if (addrs.result.suburb) cityInput.value = addrs.result.suburb;
                            else cityInput.value = addrs.result.city;
                        }

                        if (pCodeInput) pCodeInput.value = addrs.result.p_code;
                        if (countryInput) countryInput.value = addrs.result.country;

                        var stateInput = document.getElementById('geo_state');
                        if (stateInput) stateInput.value = "2";
                    }
                } catch (err) {
                    console.error("Geo Change Error", err);
                }
            });
        }
    } catch (error) {
        console.error("Geo Location Error", error);
    }
}

var citiesInput = document.getElementById("cities");
if (citiesInput) {
    citiesInput.addEventListener("change", _initLeaflet);
}

document.addEventListener("DOMContentLoaded", function() {
    _initLeaflet();
});
